    if (dot(v46, d) != 0 || dot(v57, d) != 0) { printf("N\n"); return 0; }

    // 7. |P4P6| == |P5P7|
    if (dist2(P[4], P[6]) != dist2(P[5], P[7])) { printf("N\n"); return 0; }

